};

struct State {
    int node, dist, attackers;
    bool operator>(const State& other) const {
        if (attackers != other.attackers) return attackers > other.attackers;
        return dist > other.dist;
    }
};

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int T;
    cin >> T;
    while (T--) {
        int N, M, L;
        cin >> N >> M >> L;
        vector<vector<Edge>> graph(N);
        for (int i = 0; i < M; i++) {
            int u, v, d, a;
            cin >> u >> v >> d >> a;
            graph[u].push_back({v, d, a});
            graph[v].push_back({u, d, a});
        }

        const int INF = 1e9;
        // min_attackers[node][dist] = minimum attackers to reach node with exactly this distance
        vector<vector<int>> minAttackers(N, vector<int>(L + 1, INF));
        priority_queue<State, vector<State>, greater<State>> pq;

        minAttackers[0][0] = 0;
        pq.push({0, 0, 0});

        while (!pq.empty()) {
            auto [u, d, a] = pq.top();
            pq.pop();
