        for (int i = 0; i < M; ++i) {
            int u, v, d, a;
            cin >> u >> v >> d >> a;
            g[u].push_back({v, d, a});
            g[v].push_back({u, d, a});
        }

        const int INF = 1e9;
        vector<int> bestDanger(N + 1, INF);
        vector<long long> bestDist(N + 1, (long long)4e18);

        // Dijkstra on lexicographic cost: (danger, distance)
        using State = tuple<int, long long, int>; // danger, dist, node
        priority_queue<State, vector<State>, greater<State>> pq;

        bestDanger[1] = 0;
        bestDist[1] = 0;
        pq.push({0, 0LL, 1});

        while (!pq.empty()) {
            auto [curDanger, curDist, u] = pq.top();
            pq.pop();

            if (curDanger != bestDanger[u] || curDist != bestDist[u]) continue;

            for (const auto &e : g[u]) {
                long long ndist = curDist + e.len;
                int ndanger = curDanger + e.danger;

                if (ndist > L) continue;

                if (ndanger < bestDanger[e.to] ||
                    (ndanger == bestDanger[e.to] && ndist < bestDist[e.to])) {
                    bestDanger[e.to] = ndanger;
                    bestDist[e.to] = ndist;
                    pq.push({ndanger, ndist, e.to});
                }
            }
        }

        if (bestDanger[N] == INF) cout << -1 << '\n';
