#define MAXN 105
#define INF 1000000000

typedef struct {
    int to, dist, attackers;
} Edge;

typedef struct {
    int v, dist;
} Node;

Edge graph[MAXN][MAXN];
int degree[MAXN];
int dist[MAXN][MAXN]; // shortest distance between any two nodes
int minAttackers[MAXN][MAXN]; // min attackers for a given distance budget on a path

int N, M, L;

void floydWarshall() {
    for (int i = 0; i < N; i++) {
        for (int j = 0; j < N; j++) {
            if (i == j) dist[i][j] = 0;
            else dist[i][j] = INF;
        }
    }
    for (int u = 0; u < N; u++) {
        for (int i = 0; i < degree[u]; i++) {
            int v = graph[u][i].to;
            int d = graph[u][i].dist;
            if (d < dist[u][v]) dist[u][v] = d;
        }
    }
    for (int k = 0; k < N; k++)
        for (int i = 0; i < N; i++)
            for (int j = 0; j < N; j++)
                if (dist[i][k] + dist[k][j] < dist[i][j])
                    dist[i][j] = dist[i][k] + dist[k][j];
}

int main() {
    while (1) {
        scanf("%d %d %d", &N, &M, &L);
        if (N == 0 && M == 0 && L == 0) break;

        for (int i = 0; i < N; i++) degree[i] = 0;

        for (int i = 0; i < M; i++) {
            int u, v, d, a;
            scanf("%d %d %d %d", &u, &v, &d, &a);
            u--; v--;
            graph[u][degree[u]++] = (Edge){v, d, a};
            graph[v][degree[v]++] = (Edge){u, d, a};
        }

        floydWarshall();

        // DP: dp[i][j] = min attackers from city 0 to city i with distance exactly j (or <= j)
        // Since L <= 1000, we can do DP over distance
        int dp[MAXN][1005];
        for (int i = 0; i < N; i++)
            for (int j = 0; j <= L; j++)
                dp[i][j] = INF;
        dp[0][0] = 0;

        // We'll relax edges repeatedly (Bellman-Ford style) because graph is small
        for (int distUsed = 0; distUsed <= L; distUsed++) {
            for (int u = 0; u < N; u++) {
                if (dp[u][distUsed] == INF) continue;
                for (int i = 0; i < degree[u]; i++) {
                    int v = graph[u][i].to;
                    int d = graph[u][i].dist;
                    int a = graph[u][i].attackers;
                    if (distUsed + d <= L) {
                        if (dp[u][distUsed] + a < dp[v][distUsed + d]) {
                            dp[v][distUsed + d] = dp[u][distUsed] + a;
                        }
                    }
                }
            }
        }

        int answer = INF;
        for (int d = 0; d <= L; d++) {
            if (dp[N-1][d] < answer) answer = dp[N-1][d];
        }

        if (answer == INF) printf("-1\n");
        else printf("%d\n", answer);
    }
    return 0;
}

