void addedge(int u, int v, int d, int a) {
    to[ecnt] = v; dist[ecnt] = d; att[ecnt] = a; nxt[ecnt] = head[u]; head[u] = ecnt++;
    to[ecnt] = u; dist[ecnt] = d; att[ecnt] = a; nxt[ecnt] = head[v]; head[v] = ecnt++;
}

// Priority queue: (attackers, node, dist_used)
typedef struct { int atk, node, d; } State;
State pq[MAXN * MAXL];
int pqsz;

void push(State s) { pq[pqsz++] = s; }
State pop_min() {
    int mi = 0;
    for (int i = 1; i < pqsz; i++) if (pq[i].atk < pq[mi].atk) mi = i;
    State s = pq[mi];
    pq[mi] = pq[--pqsz];
    return s;
}

int main() {
    while (scanf("%d %d %d", &N, &M, &L) == 3) {
        if (N == 0 && M == 0 && L == 0) break;
        memset(head, -1, sizeof(head));
