        for (int i = 0; i < M; i++) {
            int u, v, d, a;
            scanf("%d %d %d %d", &u, &v, &d, &a);
            u--; v--;
            addedge(u, v, d, a);
        }
        for (int i = 0; i < N; i++)
            for (int j = 0; j <= L; j++)
                dp[i][j] = INF;
        dp[0][0] = 0;
        pqsz = 0;
        State s0 = {0, 0, 0};
        push(s0);
        while (pqsz > 0) {
            State cur = pop_min();
            if (cur.atk > dp[cur.node][cur.d]) continue;
            for (int e = head[cur.node]; e != -1; e = nxt[e]) {
                int nd = cur.d + dist[e];
                if (nd > L) continue;
                int na = cur.atk + att[e];
                if (na < dp[to[e]][nd]) {
                    dp[to[e]][nd] = na;
                    State ns = {na, to[e], nd};
                    push(ns);
                }
            }
        }
        int ans = INF;
        for (int d = 0; d <= L; d++)
            if (dp[N-1][d] < ans) ans = dp[N-1][d];
        if (ans == INF) printf("-1\n");
        else printf("%d\n", ans);
    }
