typedef long long ll;

typedef struct Edge {
    int to;
    int dist;
    int thieves;
    int next;
} Edge;

typedef struct State {
    ll thieves;
    int node;
    int spent;
} State;

typedef struct MinHeap {
    State *a;
    int size;
    int cap;
} MinHeap;

static void heap_init(MinHeap *h, int cap) {
    h->a = (State *)malloc(sizeof(State) * (cap + 1));
    h->size = 0;
    h->cap = cap;
}

static void heap_free(MinHeap *h) {
    free(h->a);
}

static int state_less(State x, State y) {
    if (x.thieves != y.thieves) return x.thieves < y.thieves;
    if (x.spent != y.spent) return x.spent < y.spent;
    return x.node < y.node;
}

static void heap_push(MinHeap *h, State s) {
    if (h->size + 1 > h->cap) {
        h->cap <<= 1;
        h->a = (State *)realloc(h->a, sizeof(State) * (h->cap + 1));
    }
    int i = ++h->size;
    h->a[i] = s;
    while (i > 1) {
        int p = i >> 1;
        if (state_less(h->a[p], h->a[i])) break;
        State tmp = h->a[p];
        h->a[p] = h->a[i];
        h->a[i] = tmp;
        i = p;
    }
}

static State heap_pop(MinHeap *h) {
    State ret = h->a[1];
    h->a[1] = h->a[h->size--];
    int i = 1;
    while (1) {
        int l = i << 1, r = l + 1, best = i;
        if (l <= h->size && state_less(h->a[l], h->a[best])) best = l;
        if (r <= h->size && state_less(h->a[r], h->a[best])) best = r;
        if (best == i) break;
        State tmp = h->a[i];
        h->a[i] = h->a[best];
        h->a[best] = tmp;
        i = best;
    }
    return ret;
}

int main(void) {
    int N, M, L;

    while (scanf("%d %d %d", &N, &M, &L) == 3) {
        int *head = (int *)malloc(sizeof(int) * (N + 1));
        for (int i = 1; i <= N; i++) head[i] = -1;

        Edge *edges = (Edge *)malloc(sizeof(Edge) * (2 * M));
        int ecnt = 0;

        for (int i = 0; i < M; i++) {
            int a, b, d, t;
            scanf("%d %d %d %d", &a, &b, &d, &t);

            edges[ecnt].to = b;
            edges[ecnt].dist = d;
            edges[ecnt].thieves = t;
            edges[ecnt].next = head[a];
            head[a] = ecnt++;

            edges[ecnt].to = a;
            edges[ecnt].dist = d;
            edges[ecnt].thieves = t;
            edges[ecnt].next = head[b];
            head[b] = ecnt++;
        }

        ll INF = (ll)4e18;
        ll *dp = (ll *)malloc(sizeof(ll) * (N + 1) * (L + 1));
        for (int i = 0; i <= N; i++) {
            for (int j = 0; j <= L; j++) {
                dp[(ll)i * (L + 1) + j] = INF;
            }
        }

        MinHeap pq;
        heap_init(&pq, 1024);

        dp[1LL * (L + 1) + 0] = 0;
        heap_push(&pq, (State){0, 1, 0});

        while (pq.size) {
            State cur = heap_pop(&pq);
            ll best = dp[(ll)cur.node * (L + 1) + cur.spent];
            if (cur.thieves != best) continue;

            for (int e = head[cur.node]; e != -1; e = edges[e].next) {
                int v = edges[e].to;
                int nd = cur.spent + edges[e].dist;
                if (nd > L) continue;
                ll nt = cur.thieves + edges[e].thieves;
                ll *cell = &dp[(ll)v * (L + 1) + nd];
                if (nt < *cell) {
                    *cell = nt;
                    heap_push(&pq, (State){nt, v, nd});
                }
            }
        }

        ll ans = INF;
        for (int d = 0; d <= L; d++) {
            ll val = dp[(ll)N * (L + 1) + d];
            if (val < ans) ans = val;
        }

        if (ans == INF) printf("-1\n");
        else printf("%lld\n", ans);

        heap_free(&pq);
        free(dp);
        free(edges);
        free(head);
    }

    return 0;
}

