public class Main {
    static class Edge {
        int to, dist, attackers;
        Edge(int to, int dist, int attackers) {
            this.to = to;
            this.dist = dist;
            this.attackers = attackers;
        }
    }

    static class State implements Comparable<State> {
        int node;
        long cost;
        int attackers;
        State(int node, long cost, int attackers) {
            this.node = node;
            this.cost = cost;
            this.attackers = attackers;
        }
        public int compareTo(State other) {
            if (this.cost != other.cost) return Long.compare(this.cost, other.cost);
            return Integer.compare(this.attackers, other.attackers);
        }
    }

    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        String line;
        boolean first = true;
        while ((line = br.readLine()) != null) {
            String[] parts = line.trim().split("\\s+");
            if (parts.length < 3) continue;
            int N = Integer.parseInt(parts[0]);
            int M = Integer.parseInt(parts[1]);
            long L = Long.parseLong(parts[2]);
            if (N == 0 && M == 0 && L == 0) break;

            List<Edge>[] graph = new ArrayList[N];
            for (int i = 0; i < N; i++) graph[i] = new ArrayList<>();

            for (int i = 0; i < M; i++) {
                parts = br.readLine().trim().split("\\s+");
                int u = Integer.parseInt(parts[0]);
                int v = Integer.parseInt(parts[1]);
                int d = Integer.parseInt(parts[2]);
                int a = Integer.parseInt(parts[3]);
                graph[u].add(new Edge(v, d, a));
                graph[v].add(new Edge(u, d, a));
            }

            int result = solve(N, graph, L);
            System.out.println(result);
        }
    }

    static int solve(int N, List<Edge>[] graph, long L) {
        final int INF = Integer.MAX_VALUE / 2;
        int[][] dist = new int[N][N]; // dist[node][attackers] = min distance
        for (int i = 0; i < N; i++) Arrays.fill(dist[i], INF);

        PriorityQueue<State> pq = new PriorityQueue<>();
        dist[0][0] = 0;
        pq.offer(new State(0, 0, 0));

        while (!pq.isEmpty()) {
            State cur = pq.poll();
            int u = cur.node;
            long d = cur.cost;
            int a = cur.attackers;

            if (d != dist[u][a]) continue;

            for (Edge e : graph[u]) {
                int v = e.to;
                int nd = d + e.dist;
                int na = a + e.attackers;
                if (nd <= L && na < N && nd < dist[v][na]) {
                    dist[v][na] = nd;
                    pq.offer(new State(v, nd, na));
                }
            }
        }

        int minAttackers = INF;
        for (int a = 0; a < N; a++) {
            if (dist[N-1][a] <= L) {
                minAttackers = a;
                break;
            }
        }
        return minAttackers == INF ? -1 : minAttackers;
    }
}

