import java.io.*;
import java.util.*;

/*
We need the minimum total attackers among all paths from 1 to N
whose total distance is <= L.

Model:
- vertices: waypoints
- edge has:
    d = distance cost
    a = attackers on that road
- objective: minimize sum(a) subject to sum(d) <= L

Classic DP shortest path on resource:
dp[v][c] = minimum attackers to reach v with exact distance c
Answer = min(dp[N][c]) for c <= L

Transitions:
dp[to][c + d] = min(dp[to][c + d], dp[v][c] + a)

Since all distances are nonnegative and graph is undirected (roads between waypoints),
we process states with Dijkstra-like search on attackers as primary cost over expanded graph
(state = (vertex, usedDistance)).
This avoids scanning all impossible states too much, while remaining correct.

Input consists of multiple datasets until EOF.
For each dataset: N M L
Then M lines: u v d a

Output one line per dataset: minimum attackers.
If unreachable within budget, print -1.
*/

public class Main {
    static class FastScanner {
        private final InputStream in;
        private final byte[] buffer = new byte[1 << 16];
        private int ptr = 0, len = 0;

        FastScanner(InputStream is) {
            in = is;
        }

        private int read() throws IOException {
            if (ptr >= len) {
                len = in.read(buffer);
                ptr = 0;
                if (len <= 0) return -1;
            }
            return buffer[ptr++];
        }

        int nextInt() throws IOException {
            int c;
            do {
                c = read();
                if (c == -1) return Integer.MIN_VALUE;
            } while (c <= ' ');

            int sign = 1;
            if (c == '-') {
                sign = -1;
                c = read();
            }

            int val = 0;
            while (c > ' ') {
                val = val * 10 + (c - '0');
                c = read();
            }
            return val * sign;
        }
    }

    static class Edge {
        int to, dist, att;
        Edge(int to, int dist, int att) {
            this.to = to;
            this.dist = dist;
            this.att = att;
        }
    }

    static class State implements Comparable<State> {
        int node, used, att;
        State(int node, int used, int att) {
            this.node = node;
            this.used = used;
            this.att = att;
        }
        public int compareTo(State o) {
            return Integer.compare(this.att, o.att);
        }
    }

    public static void main(String[] args) throws Exception {
        FastScanner fs = new FastScanner(System.in);
        StringBuilder out = new StringBuilder();

        while (true) {
            int N = fs.nextInt();
            if (N == Integer.MIN_VALUE) break;
            int M = fs.nextInt();
            int L = fs.nextInt();

            List<Edge>[] g = new ArrayList[N + 1];
            for (int i = 1; i <= N; i++) g[i] = new ArrayList<>();

            for (int i = 0; i < M; i++) {
                int u = fs.nextInt();
                int v = fs.nextInt();
                int d = fs.nextInt();
                int a = fs.nextInt();
                g[u].add(new Edge(v, d, a));
                g[v].add(new Edge(u, d, a));
            }

            int ans = solve(N, L, g);
            out.append(ans).append('\n');
        }

        System.out.print(out.toString());
    }

    static int solve(int N, int L, List<Edge>[] g) {
        final int INF = Integer.MAX_VALUE / 4;

        int[][] best = new int[N + 1][L + 1];
        for (int i = 1; i <= N; i++) Arrays.fill(best[i], INF);

        PriorityQueue<State> pq = new PriorityQueue<>();
        best[1][0] = 0;
        pq.add(new State(1, 0, 0));

        while (!pq.isEmpty()) {
            State cur = pq.poll();
            if (cur.att != best[cur.node][cur.used]) continue;

            for (Edge e : g[cur.node]) {
                int nd = cur.used + e.dist;
                if (nd > L) continue;
                int na = cur.att + e.att;
                if (na < best[e.to][nd]) {
                    best[e.to][nd] = na;
                    pq.add(new State(e.to, nd, na));
                }
            }
        }

        int ans = INF;
        for (int d = 0; d <= L; d++) ans = Math.min(ans, best[N][d]);
        return ans == INF ? -1 : ans;
    }
}
